cat > binlog-reader/Program.cs << 'CEOF'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors and warnings
var errors = build.FindChildrenRecursive<Error>().ToList();
var warnings = build.FindChildrenRecursive<Warning>().ToList();

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine($"Total warnings: {warnings.Count}");
Console.WriteLine();

Console.WriteLine("=== ERRORS ===");
foreach (var e in errors)
{
    var project = e.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    Console.WriteLine($"[{projectName}] {e.Code}: {e.Text}");
    if (!string.IsNullOrEmpty(e.File))
        Console.WriteLine($"  File: {e.File}({e.LineNumber},{e.ColumnNumber})");
    Console.WriteLine();
}

Console.WriteLine("=== WARNINGS (first 30) ===");
foreach (var w in warnings.Take(30))
{
    var project = w.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    Console.WriteLine($"[{projectName}] {w.Code}: {w.Text}");
    if (!string.IsNullOrEmpty(w.File))
        Console.WriteLine($"  File: {w.File}({w.LineNumber},{w.ColumnNumber})");
    Console.WriteLine();
}

// Show project build order and results
Console.WriteLine("=== PROJECT RESULTS ===");
var projects = build.FindChildrenRecursive<Project>().ToList();
foreach (var p in projects)
{
    var projErrors = p.FindChildrenRecursive<Error>().ToList();
    Console.WriteLine($"  {p.Name} -> Succeeded={p.Succeeded}, Errors={projErrors.Count}");
}
