cd /tmp/sv-18032e9ef4bc42a1bed7d89e414592eb && cat > binlog-reader/Program.cs << 'CEOF'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check for MSBuild-level errors (like dependency build failures)
Console.WriteLine("=== ALL MESSAGES WITH 'error' or 'fail' ===");
var messages = build.FindChildrenRecursive<Message>().ToList();
foreach (var m in messages.Where(m => m.Text != null && (m.Text.Contains("error", StringComparison.OrdinalIgnoreCase) || m.Text.Contains("fail", StringComparison.OrdinalIgnoreCase))))
{
    var project = m.GetNearestParent<Project>();
    Console.WriteLine($"[{project?.Name ?? "?"}] {m.Text}");
}

Console.WriteLine();
Console.WriteLine("=== DEPENDENCY GRAPH ===");
var projects = build.FindChildrenRecursive<Project>().ToList();
foreach (var p in projects.DistinctBy(p => p.Name))
{
    var refs = p.FindChildrenRecursive<Item>()
        .Where(i => i.Name == "ProjectReference")
        .Select(i => i.Text)
        .Distinct()
        .ToList();
    if (refs.Any())
    {
        Console.WriteLine($"{p.Name} depends on:");
        foreach (var r in refs) Console.WriteLine($"  -> {r}");
    }
}
